'use strict';
// Windows events as a Wazuh manager writes them to /var/ossec/logs/archives/archives.json (one JSON object per line; `<logall_json>yes</logall_json>`).
// Shape: data.win.system (providerName, eventID, channel, computer, systemTime, message ...) and data.win.eventdata (the event's named data, with the FIRST letter
// of every name lower-cased: Windows' TargetUserName is written targetUserName). The messages keep Windows' own line breaks (\r\n) and tabs, and Wazuh wraps them in quotes.
// These are hand-made samples of that documented shape, not captures from a live manager: E4b (installing the manager) is where one real event of each kind gets checked.
const lower = (o) => Object.fromEntries(Object.entries(o).map(([k, v]) => [k[0].toLowerCase() + k.slice(1), v]));
const crlf = (s) => '"' + s.replace(/\n/g, '\r\n').replace(/ {2}/g, '\t') + '"';

